#@ requires 1 == 1
    #@ ensures 1 == 1
    #@ assigns \nothing
    def uses_sum(obj: Any) -> bool:
        if isinstance(obj, dict):
            if obj.get("type") == "Sum":
                return True
            return any(IRScanner.uses_sum(v) for v in obj.values())
        if isinstance(obj, list):
            return any(IRScanner.uses_sum(item) for item in obj)
        return False
